
import type { OrderDeliveryDestinationAddressInput } from './OrderDeliveryDestinationAddressInput.js';
import type { OrderDeliveryDestinationRecipientInput } from './OrderDeliveryDestinationRecipientInput.js';
import type { RequestedTipInput } from './RequestedTipInput.js';

export type OrderInput = { "active_payment_attempt"?: never; "applied_discounts"?: never; "authorization_amounts"?: never; /** What the buyer can do with the order, in this order: start_return, then resend_receipt. A buyer's read through a customer session on /v1/me, or in Flint's buyer account, lists both every time; a merchant read gets an empty list. A list of orders leaves start_return out, since only a read of one order checks return eligibility. start_return is due when the last open return window ends. Example: []. */ "buyer_actions"?: never; "buyer_email"?: never; "buyer_note"?: string; /** Phone the buyer gave when payment started, in E.164 format: the pay request's buyer_phone, or the phone saved on the paying checkout session. It does not change the linked customer. */ "buyer_phone"?: never; "charges"?: never; "checkout_session_ids"?: never; /** Internal reason supplied when the order was closed. This is not shown to the buyer. */ "closed_reason"?: never; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; "customer"?: never; "customer_id"?: string; /** The shipment or local-delivery destination committed for this order. Payment freezes this value; fulfillment recipient changes do not replace it. */ "delivery_destination"?: { "address": OrderDeliveryDestinationAddressInput; /** Delivery selection that controls this destination, when checkout collected it. */ "delivery_selection_id"?: string; /** Time payment froze this destination. Format: date-time. */ "frozen_at"?: string | globalThis.Date; "recipient"?: OrderDeliveryDestinationRecipientInput; "source": "delivery_selection" | "api" | "dashboard"; }; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "fulfillment_status"?: never; "fulfillments"?: never; "gift_card_estimate"?: never; "gift_card_settlements"?: never; "gift_card_tender_enabled"?: never; "gift_cards"?: never; "internal_note"?: string; "inventory_exception_status"?: never; /** The reservation holding stock for this order, when one exists. */ "inventory_reservation_id"?: never; /** Where this order's tracked demand is routed. Required before an order containing tracked variants can hold stock. */ "inventory_routing_source"?: { "inventory_allocation_policy_id"?: string; "inventory_allocation_policy_version_id"?: string; "location_id"?: string; "location_ids"?: Array<string>; "type": "fixed_location" | "policy" | "policy_version"; }; "line_items"?: never; "merchant_id"?: never; "metadata"?: Record<string, string>; "order_id"?: never; "order_number"?: never; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "order_revision"?: never; "origin"?: never; "payment_collection"?: never; "payment_intent_ids"?: never; "payment_intents"?: never; "payment_status"?: never; "plan_id"?: never; "pricing_amounts"?: never; "purchased_event"?: never; "refund_ids"?: never; "refund_status"?: never; "requested_tip"?: RequestedTipInput; /** Value applied to this order from items the buyer returned, such as an exchange's replacement order. Included in settlement_amounts.paid_money. */ "return_credit_settlements"?: never; "settlement_amounts"?: never; "setup_collection"?: never; "status"?: never; "subscription"?: never; "subscription_id"?: never; "subscription_plan"?: never; "tax"?: never; "tips"?: never; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; };
